interface Window {
  $: JQueryStatic;
  jQuery: JQueryStatic;
}

declare module 'jquery' {
  export = jQuery;
}

declare module '*.svg' {
  const content: string;
  export default content;
}

declare module '*.png' {
  const content: string;
  export default content;
}

declare module '*.jpg' {
  const content: string;
  export default content;
}

declare module '*.jpeg' {
  const content: string;
  export default content;
} 